"""Render one row of the build table."""


def row(name, label):
    return f"{name}: {label}"

"""Map a build's raw status to the label the dashboard shows."""

LABELS = {"ok": "passed", "fail": "failed"}


def label(raw):
    return LABELS.get(raw.lower(), "unknown")

